#!/bin/sh
# Build the sandbox image and prove Trivy works under EXACTLY the restrictions DockerSandbox applies.
# The docker command is generated by the production code (DockerSandbox.build_args), so it cannot drift.
#   sandbox/scripts/verify-trivy.sh            (needs Docker, network for the build only, and the backend venv)
set -eu
cd "$(dirname "$0")/../.."
IMG="${SANDBOX_IMAGE:-aesa-sandbox:latest}"

echo "== 1. build (also asserts the baked DB fits the runtime tmpfs budget)"
docker build -t "$IMG" --build-arg "TRIVY_TMPFS_MB=${TRIVY_TMPFS_MB:-1200}" sandbox

echo "== 2. the exact docker command the backend will run for trivy_fs"
(cd backend && JWT_SECRET=x python - <<'PY'
from pathlib import Path
from app.config import Settings
from app.sandbox.commands import CommandRegistry
from app.sandbox.runner import DockerSandbox
s = Settings(_env_file=None, jwt_secret="x" * 40)
print(" ".join(DockerSandbox(s).build_args(CommandRegistry(s).plan("trivy_fs", {}), Path("/path/to/workspace"), "aesa-demo")))
PY
)

echo "== 3. DB size baked into the image"
docker run --rm --entrypoint sh "$IMG" -c 'du -sh /opt/trivy-db/db; ls -l /opt/trivy-db/db'

echo "== 4. integration tests through DockerSandbox.run (real container, production flags)"
(cd backend && python -m pytest -q -rs tests/test_docker_sandbox_integration.py)

echo "OK: trivy_fs ran read-only, offline, non-root, capability-free, against the baked DB."
